func partition(s string) [][]string {
	n := len(s)
	ok := make([][]bool, n)
	for i := range ok {
		ok[i] = make([]bool, n)
	}
	for i := n - 1; i >= 0; i-- {
		for j := i; j < n; j++ {
			ok[i][j] = s[i] == s[j] && (j-i < 2 || ok[i+1][j-1])
		}
	}
	res := [][]string{}
	path := []string{}
	var dfs func(start int)
	dfs = func(start int) {
		if start == n {
			res = append(res, append([]string{}, path...))
			return
		}
		for end := start; end < n; end++ {
			if ok[start][end] {
				path = append(path, s[start:end+1])
				dfs(end + 1)
				path = path[:len(path)-1]
			}
		}
	}
	dfs(0)
	return res
}

