func solveNQueens(n int) [][]string {
	cols, d1, d2 := map[int]bool{}, map[int]bool{}, map[int]bool{}
	res := [][]string{}
	board := []string{}
	var dfs func(r int)
	dfs = func(r int) {
		if r == n {
			res = append(res, append([]string{}, board...))
			return
