				continue
			}
			cols[c], d1[r-c], d2[r+c] = true, true, true
			board = append(board, strings.Repeat(".", c)+"Q"+strings.Repeat(".", n-c-1))
			dfs(r + 1)
			board = board[:len(board)-1]
			cols[c], d1[r-c], d2[r+c] = false, false, false
		}
	}
	dfs(0)
	return res
}

