func searchRange(nums []int, target int) []int {
	n := len(nums)
	lower := func(v int) int {
		l, r := 0, n
		for l < r {
			mid := (l + r) / 2
			if nums[mid] < v {
				l = mid + 1
			} else {
				r = mid
			}
		}
		return l
	}
	left := lower(target)
	if left == n || nums[left] != target {
		return []int{-1, -1}
	}
	return []int{left, lower(target+1) - 1}
}

