import "math"

func findMedianSortedArrays(nums1 []int, nums2 []int) float64 {
	a, b := nums1, nums2
	if len(a) > len(b) {
		a, b = b, a
	}
	m, n := len(a), len(b)
	half := (m + n + 1) / 2
	l, r := 0, m
	for l <= r {
		i := (l + r) / 2
		j := half - i
		la, ra := math.Inf(-1), math.Inf(1)
		lb, rb := math.Inf(-1), math.Inf(1)
		if i > 0 {
			la = float64(a[i-1])
		}
		if i < m {
			ra = float64(a[i])
		}
		if j > 0 {
			lb = float64(b[j-1])
		}
		if j < n {
			rb = float64(b[j])
		}
		if la <= rb && lb <= ra {
			if (m+n)%2 == 1 {
				return math.Max(la, lb)
			}
			return (math.Max(la, lb) + math.Min(ra, rb)) / 2
		}
		if la > rb {
			r = i - 1
		} else {
			l = i + 1
		}
	}
	return 0.0
}

