func decodeString(s string) string {
	type pair struct {
		s string
		k int
	}
	stack := []pair{}
	cur, k := "", 0
	for i := 0; i < len(s); i++ {
		ch := s[i]
		if ch >= '0' && ch <= '9' {
			k = k*10 + int(ch-'0')
		} else if ch == '[' {
			stack = append(stack, pair{cur, k})
			cur, k = "", 0
		} else if ch == ']' {
			p := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			cur = p.s + strings.Repeat(cur, p.k)
		} else {
			cur += string(ch)
		}
	}
	return cur
}

