func largestRectangleArea(heights []int) int {
	hs := make([]int, 0, len(heights)+2)
	hs = append(hs, 0)
	hs = append(hs, heights...)
	hs = append(hs, 0)
	stack := []int{}
	best := 0
	for i, h := range hs {
		for len(stack) > 0 && hs[stack[len(stack)-1]] > h {
			top := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			area := hs[top] * (i - stack[len(stack)-1] - 1)
			if area > best {
				best = area
			}
		}
		stack = append(stack, i)
	}
	return best
}

