func (h *intHeap) push(v int) {
	h.a = append(h.a, v)
	i := len(h.a) - 1
	for i > 0 {
		p := (i - 1) / 2
		if h.a[i] >= h.a[p] {
			break
		}
		h.a[i], h.a[p] = h.a[p], h.a[i]
		i = p
	}
}

func (h *intHeap) pop() int {
	top := h.a[0]
	last := h.a[len(h.a)-1]
	h.a = h.a[:len(h.a)-1]
	if len(h.a) > 0 {
		h.a[0] = last
		i := 0
		for {
			m := i
			l, r := 2*i+1, 2*i+2
			if l < len(h.a) && h.a[l] < h.a[m] {
				m = l
			}
			if r < len(h.a) && h.a[r] < h.a[m] {
				m = r
			}
			if m == i {
				break
			}
			h.a[i], h.a[m] = h.a[m], h.a[i]
			i = m
		}
	}
	return top
}

